import { Result, Button } from 'antd'
import { useHistory } from 'react-router'
import { get } from 'lodash'

export default function ResultComponent () {
  const history = useHistory()

  const backPageRoute = () => {
    history.goBack()
  }

  return (
    <Result
      status='success'
      title='Successfully Generated API Spec!'
      extra={[
        <Button href={get(history, 'location.state.data.details.pdf_url', '')} target='_blank' key='pdf link' type='primary'>
          PDF View
        </Button>,
        <Button key='back' onClick={backPageRoute}>Back</Button>
      ]}
    />
  )
}
